<?php require __DIR__.'/../header.php';require __DIR__.'/../navbar.php';?><main class="container-fluid py-4 px-lg-4"><div class="d-flex justify-content-between align-items-center mb-3"><div><h2 class="mb-0"><?=esAdministrador()?'Pagos registrados':'Mis pagos'?></h2><span class="text-secondary">Cobros y dinero recibido.</span></div><a class="btn btn-primary" href="index.php?c=pago&a=crear">+ Registrar pago</a></div><div class="card"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Fecha</th><?php if(esAdministrador()):?><th>Vendedor</th><?php endif;?><th>Campaña / Venta</th><th>Monto</th><th>Medio</th><th>Observación</th></tr></thead><tbody><?php if(!$pagos):?><tr><td colspan="6" class="vacio">No hay pagos registrados.</td></tr><?php else:foreach($pagos as $p):?><tr><td><?=e($p['fecha_pago'])?></td><?php if(esAdministrador()):?><td><?=e($p['vendedor'])?></td><?php endif;?><td><?=e($p['campania'])?><small class="d-block text-secondary">Venta #<?=e($p['venta_id'])?> · <?=e($p['cliente'])?></small></td><td><strong>$<?=number_format($p['monto'],2,',','.')?></strong></td><td><?=e($p['medio_pago'])?></td><td><?=e($p['observacion'])?></td></tr><?php endforeach;endif;?></tbody></table></div></div></main><?php require __DIR__.'/../footer.php';?>
